  hrana: [
    { ime: "Tortilla de patatas", opis: "Debeli omlet od jaja i krumpira polako kuhanog u maslinovu ulju, s lukom ili bez njega.", prica: "Pitanje treba li u tortilju ići luk dijeli Španjolce ozbiljnije od nogometa, pa su se uvriježila dva tabora, concebollistas i sincebollistas. Jede se topla ili hladna, kao kriška na šanku ili u sendviču. U dobroj tortilji sredina ostaje sočna i gotovo tekuća." },
    { ime: "Jamón ibérico", opis: "Pršut od crne iberske svinje, sušen dvije do četiri godine i rezan nožem na gotovo prozirne listiće.", prica: "Najcjenjeniji nosi oznaku de bellota, što znači da se svinja u jesen slobodno hranila žirom u hrastovim šumama zvanima dehesa. Na crnu boju papka aludira i pučki naziv pata negra. Ne miješajte ga s jamón serrano, koji se radi od bijele svinje i znatno je jeftiniji." },
    { ime: "Paella valenciana", opis: "Riža kuhana u širokoj plitkoj tavi s piletinom, zecom, mahunama, velikim bijelim grahom i šafranom.", prica: "Nastala je kao ručak seljaka na rižinim poljima oko lagune Albufera kraj Valencije, i izvorna inačica ne sadrži plodove mora. Španjolci je jedu isključivo za ručak. Najcjenjeniji je zalogaj socarrat, hrskava kora riže koja se uhvatila za dno tave." },
    { ime: "Gazpacho i salmorejo", opis: "Hladne juhe od zrele rajčice, kruha, češnjaka i maslinova ulja, spas u andaluzijskom ljetu.", prica: "Gazpacho je rjeđi, sadrži i krastavac i papriku i često se pije iz čaše. Salmorejo potječe iz Córdobe, gust je poput kreme i poslužuje se s naribanim kuhanim jajetom i kockicama pršuta. Zanimljivo je da su prethodnici tih juha postojali i prije nego što je rajčica stigla iz Amerike, kao mješavina kruha, češnjaka, ulja i octa." },
    { ime: "Croquetas", opis: "Kroketi od gustog bešamela s pršutom, piletinom ili bakalarom, hrskavi izvana i kremasti iznutra.", prica: "Nastali su kao način da se iskoristi meso preostalo od nedjeljnog variva. Mnogi Španjolci tvrde da se kvaliteta bara najbolje procjenjuje upravo po kroketima, a najbolji su, dakako, uvijek oni koje radi baka." },
    { ime: "Pulpo á feira", opis: "Kuhana hobotnica narezana škarama na kolutiće, začinjena krupnom solju, slatkom i ljutom paprikom i maslinovim uljem.", prica: "Galicijsko jelo koje se tradicionalno pripremalo na stočnim sajmovima, odakle mu i ime. Hobotnicu kuhaju žene zvane pulpeiras u velikim bakrenim kotlovima, a poslužuje se na drvenom tanjuru. Španjolci je na ostatku poluotoka zovu pulpo a la gallega." },
    { ime: "Pintxos", opis: "Baskijski zalogaji na kriški kruha, često probodeni čačkalicom, koji se jedu stojeći za šankom.", prica: "Ime dolazi od glagola pinchar, što znači nabosti. Običaj je u jednom baru pojesti jedan ili dva zalogaja uz malu čašu vina ili piva, pa krenuti u sljedeći. Hladni stoje na šanku, a tople treba naručiti s ploče na zidu." },
    { ime: "Churros con chocolate", opis: "Prženo tijesto u obliku rebrastih štapića koje se umače u vrlo gustu vruću čokoladu.", prica: "Jedu se za doručak ili u zoru, nakon noćnog izlaska. Deblja i mekša inačica zove se porra. U Madridu se od 1894. poslužuju u čokolateriji San Ginés, koja se, kako sama ističe, nikada ne zatvara." },
    { ime: "Vino de Jerez", opis: "Pojačano vino iz trokuta gradova Jerez de la Frontera, Sanlúcar de Barrameda i El Puerto de Santa María, u svijetu poznato kao sherry.", prica: "Dozrijeva u sustavu solera, u kojem se mlado vino postupno miješa sa starijim, pa svaka boca sadrži kapljice iz mnogih berbi. Fino i manzanilla suhi su i blijedi, čuvaju se pod slojem kvasca i piju hladni uz masline i pršut. Oloroso je taman i miriše na orahe, dok je Pedro Ximénez gust i sladak poput sirupa." },
    { ime: "Vermut i tinto de verano", opis: "Dva pića uz koja Španjolci provode sate prije ručka i ljetne večeri.", prica: "La hora del vermut običaj je nedjeljnog aperitiva prije ručka, uz masline i čips, osobito u Madridu i Kataloniji. Tinto de verano mješavina je crnog vina i gaziranog soka od limuna, i upravo njega, a ne sangriju, ljeti naručuju domaći." }
  ],
  obicaji: [
    { ime: "Flamenco", opis: "Umjetnost koja spaja pjevanje zvano cante, gitaru i ples, a nastala je u Andaluziji iz susreta romske, maurske, židovske i andaluzijske pučke glazbe. Od 2010. nalazi se na UNESCO-ovu popisu nematerijalne baštine. Traži se duende, trenutak u kojem izvođača i publiku obuzme osjećaj koji se ne može odglumiti.", gdje: "Sevilla, osobito četvrt Triana, zatim Jerez de la Frontera i špilje Sacromontea u Granadi. Tečajeve za početnice nude škole u Sevilli, Granadi i Madridu, a Bienal de Flamenco održava se u Sevilli u rujnu parnih godina." },
    { ime: "Semana Santa", opis: "Veliki tjedan, u kojem bratovštine nose ulicama teške nosiljke s kipovima Krista i Bogorodice, zvane pasos. Prate ih pokornici zvani nazarenos, sa šiljastim kapuljačama, koje su mnogo starije od svake druge asocijacije koju bi mogle pobuditi. S balkona se katkad začuje saeta, molitva otpjevana na način flamenca.", gdje: "Sevilla, Málaga, Granada i Valladolid, u tjednu prije Uskrsa." },
    { ime: "Castells", opis: "Ljudske kule visoke do deset katova, koje u Kataloniji grade skupine zvane colles. Na vrh se penje dijete, enxaneta, koje podizanjem ruke označava da je kula dovršena. Običaj je od 2010. zaštićen kao UNESCO-ova nematerijalna baština, a moto mu je snaga, ravnoteža, hrabrost i razum.", gdje: "Tarragona, Valls i Vilafranca del Penedès te Barcelona tijekom svetkovine La Mercè oko 24. rujna. Sezona traje od proljeća do studenoga." },
    { ime: "Las Fallas", opis: "Valencijska svetkovina u čast svetog Josipa, tijekom koje se na trgovima podižu goleme satirične skulpture od drva i kartona. U noći 19. ožujka sve se spaljuju u obredu zvanom cremà. Svetkovina je od 2016. na UNESCO-ovu popisu nematerijalne baštine.", gdje: "Valencia, od 15. do 19. ožujka, uz svakodnevnu pucnjavu petardi zvanu mascletà od početka mjeseca." },
    { ime: "Feria de Abril", opis: "Tjedan dana plesa, konja i šarenih haljina na sajmištu s više od tisuću šatora zvanih casetas. Pleše se sevillana, ples u parovima u četiri dijela, koji možete naučiti u jednom popodnevu. Većina je šatora privatna, no postoje i javni, u koje može ući svatko.", gdje: "Sevilla, obično dva tjedna nakon Uskrsa." },
    { ime: "Tapeo", opis: "Običaj obilaska nekoliko barova u nizu, pri čemu se u svakom popije piće i pojede mali zalogaj. Jedno od objašnjenja naziva kaže da se čaša nekoć pokrivala kriškom kruha ili pršuta kako u nju ne bi upale mušice, jer tapa znači poklopac. Jede se stojeći, a u nekim gradovima, poput Granade, zalogaj se dobiva besplatno uz svako piće.", gdje: "Posvuda, a osobito u Sevilli, Granadi, Madridu u četvrti La Latina i u baskijskim gradovima, gdje se tapasi zovu pintxos." },
    { ime: "Sobremesa", opis: "Vrijeme koje se nakon jela provodi za stolom u razgovoru, uz kavu ili čašicu likera, i koje može potrajati dulje od samog ručka. Konobar vam neće donijeti račun dok ga ne zatražite, jer bi to bilo nepristojno. Poslijepodnevni odmor, siesta, danas je više stvar malih mjesta i ljetnih vrućina nego velikih gradova, no mnoge se trgovine i dalje zatvaraju od dva do pet.", gdje: "U svakom restoranu, osobito nedjeljom." }
  ],
