        { ime: "Runner Bean Tours", opis: "Lokalna tvrtka poznata po pješačkim turama Gotičkom četvrti i Gaudíjevim građevinama, koje se plaćaju napojnicom.", link: "https://runnerbeantours.com/" },
        { ime: "Sagrada Família", opis: "Službena stranica bazilike, jedino mjesto na kojem se ulaznice za određeni termin kupuju bez posrednika.", link: "https://sagradafamilia.org/en/" }
